class Queen {

    private final int row;
    private final int column;

    Queen(int row, int column) {
        if (row < 0) {
            throw new IllegalArgumentException("Queen position must have positive row.");
        }
        if (row > 7) {
            throw new IllegalArgumentException("Queen position must have row <= 7.");
        }
        if (column < 0) {
            throw new IllegalArgumentException("Queen position must have positive column.");
        }
        if (column > 7) {
            throw new IllegalArgumentException("Queen position must have column <= 7.");
        }
        this.row = row;
        this.column = column;
    }

    int row() {
        return row;
    }

    int column() {
        return column;
    }

}

class QueenAttackCalculator {

    private final Queen whiteQueen;
    private final Queen blackQueen;

    QueenAttackCalculator(Queen queen1, Queen queen2) {
        if (queen1 == null || queen2 == null) {
            throw new IllegalArgumentException("You must supply valid positions for both Queens.");
        }
        if (queen1.row() == queen2.row() && queen1.column() == queen2.column()) {
            throw new IllegalArgumentException("Queens cannot occupy the same position.");
        }
        this.whiteQueen = queen1;
        this.blackQueen = queen2;
    }

    boolean canQueensAttackOneAnother() {
        int rowDiff = Math.abs(whiteQueen.row() - blackQueen.row());
        int columnDiff = Math.abs(whiteQueen.column() - blackQueen.column());

        return rowDiff == 0
                || columnDiff == 0
                || rowDiff == columnDiff;
    }

}
